DELETE FROM `edu_course` WHERE `id` > 20;
DELETE FROM `edu_category` WHERE `id` > 10;

USE `share`;

-- 2. 批量插入 100 名真实 IT 学员到 sys_user

-- 3. 关联角色：为 100 名学员赋予学生角色 (role_id = 2)

USE `tj_education`;

